function validate([points]) {
  if (!Array.isArray(points) || points.length < 1) return 'points needs at least one row.';
  const n = points[0].length;
  if (n < 1) return 'Each row needs at least one cell.';
  if (points.some(row => !Array.isArray(row) || row.length !== n)) return 'All rows must have the same length.';
  if (points.length * n > 100000) return 'm * n is at most 10^5.';
  if (points.some(row => row.some(v => !Number.isInteger(v) || v < 0 || v > 100000))) return 'Each value is between 0 and 10^5.';
  return null;
}

