function maxPoints(points) {
  const cols = points[0].length;
  let prev = points[0].slice();
  for (let r = 1; r < points.length; r++) {
    const fromLeft = new Array(cols);
    fromLeft[0] = prev[0];
    for (let c = 1; c < cols; c++) {
      fromLeft[c] = Math.max(fromLeft[c - 1] - 1, prev[c]);
    }
    const fromRight = new Array(cols);
    fromRight[cols - 1] = prev[cols - 1];
    for (let c = cols - 2; c >= 0; c--) {
      fromRight[c] = Math.max(fromRight[c + 1] - 1, prev[c]);
    }
    const current = new Array(cols);
    for (let c = 0; c < cols; c++) {
      current[c] = points[r][c] + Math.max(fromLeft[c], fromRight[c]);
    }
    prev = current;
  }
  return prev.reduce((best, value) => Math.max(best, value));
}

