function maxPoints(points) {
  // Plain DP: try every column of the previous row for every cell.
  const n = points[0].length;
  let row = [...points[0]];
  for (let r = 1; r < points.length; r++) {
    const next = [];
    for (let c = 0; c < n; c++) {
      let best = -Infinity;
      for (let k = 0; k < n; k++) best = Math.max(best, row[k] - Math.abs(k - c));
      next.push(best + points[r][c]);
    }
    row = next;
  }
  return Math.max(...row);
}

