function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let m, n, top;
  if (size === 'large') {
    const shape = int(0, 3);
    [m, n] = shape === 0 ? [100, 100] : shape === 1 ? [int(2, 10), 100] : shape === 2 ? [100, int(2, 10)] : [int(30, 100), int(30, 100)];
    top = rand() < 0.5 ? 100000 : int(50, 300);
  } else {
    m = int(1, 5);
    n = int(1, 6);
    top = rand() < 0.2 ? 100000 : int(0, 12);
  }
  const points = Array.from({ length: m }, () => Array.from({ length: n }, () => int(0, top)));
  return [points];
}
